package com.vyrewatchhelper;

import javax.inject.Inject;
import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemSpawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.Notifier;
import net.runelite.client.ui.overlay.OverlayManager;
import java.awt.TrayIcon;
import java.time.Instant;

@Slf4j
@PluginDescriptor(
        name = "Vyrewatch Sentinel Helper",
        description = "Helpers for camping Vyrewatch Sentinels for Blood Shards",
        tags = {"combat", "vyre", "afk", "blood shard"}
)
public class VyrewatchHelperPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private VyrewatchHelperconfig config;

    @Inject
    private Notifier notifier;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private VyrewatchHelperStatsOverlay statsOverlay;

    @Getter private int killCount = 0;
    @Getter private int shardCount = 0;
    @Getter private Instant startTime = null;
    @Getter private boolean trackingStarted = false;

    // Cooldown timer to prevent notifications screaming every 0.6 seconds
    private Instant lastPrayerAlertTime = Instant.EPOCH;
    private static final int ALERT_COOLDOWN_SECONDS = 10;

    @Provides
    VyrewatchHelperconfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(VyrewatchHelperconfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        overlayManager.add(statsOverlay);
        log.info("Vyrewatch Sentinel Helper started!");
    }

    @Override
    protected void shutDown() throws Exception
    {
        overlayManager.remove(statsOverlay);
        resetTracker();
        log.info("Vyrewatch Sentinel Helper stopped!");
    }

    private void resetTracker()
    {
        killCount = 0;
        shardCount = 0;
        startTime = null;
        trackingStarted = false;
    }

    @Subscribe
    public void onActorDeath(ActorDeath event)
    {
        Actor actor = event.getActor();

        if (actor instanceof NPC)
        {
            NPC npc = (NPC) actor;
            String name = npc.getName();

            if (name != null && name.contains("Vyrewatch Sentinel") && npc.getInteracting() == client.getLocalPlayer())
            {
                if (!trackingStarted)
                {
                    startTime = Instant.now();
                    trackingStarted = true;
                }
                killCount++;
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }

        if (config.lowPrayerAlert())
        {
            int currentPrayer = client.getBoostedSkillLevel(Skill.PRAYER);
            if (currentPrayer <= config.prayerThreshold())
            {
                // Only alert if 10 seconds have passed since the last alert
                if (Instant.now().isAfter(lastPrayerAlertTime.plusSeconds(ALERT_COOLDOWN_SECONDS)))
                {
                    notifier.notify("Your prayer is getting low! Use the altar!");
                    lastPrayerAlertTime = Instant.now();
                }
            }
        }
    }

    @Subscribe
    public void onItemSpawned(ItemSpawned event)
    {
        if (!config.bloodShardAlert())
        {
            return;
        }

        TileItem item = event.getItem();

        if (item.getId() == ItemID.BLOOD_SHARD)
        {
            // Ensure the shard dropped within 3 tiles of your player
            // to protect against counting other people's distant loot.
            Player localPlayer = client.getLocalPlayer();
            if (localPlayer != null)
            {
                LocalPoint playerLocation = localPlayer.getLocalLocation();
                LocalPoint itemLocation = event.getTile().getLocalLocation();
                if (playerLocation.distanceTo(itemLocation) > 3 * Perspective.LOCAL_TILE_SIZE)
                {
                    return;
                }
            }

            shardCount++;
            notifier.notify("🔴 BLOOD SHARD DROPPED! 🔴", TrayIcon.MessageType.WARNING);

            // Replaced missing symbol reference with raw game engine sound ID constant
            client.playSoundEffect(3892);
        }
    }
}

package com.vyrewatchhelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public class VyrewatchHelperStatsOverlay extends OverlayPanel
{
    private final VyrewatchHelperPlugin plugin;

    // Optimization: Cache static color objects to prevent recreating them mid-render
    private static final Color TITLE_COLOR = Color.GREEN;
    private static final Color SHARD_DROP_COLOR = Color.RED;
    private static final Color DEFAULT_TEXT_COLOR = Color.WHITE;

    @Inject
    private VyrewatchHelperStatsOverlay(VyrewatchHelperPlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!plugin.isTrackingStarted() || plugin.getStartTime() == null)
        {
            return null;
        }

        // CRITICAL FIX: Clear last frame's components to prevent an infinite memory leak accumulation
        panelComponent.getChildren().clear();

        // 1. Add Title
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Vyre Tracker")
                .color(TITLE_COLOR)
                .build());

        // 2. Add Kill Count
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Kills:")
                .right(String.valueOf(plugin.getKillCount()))
                .build());

        // 3. Add Shards Collected
        int shardCount = plugin.getShardCount();
        panelComponent.getChildren().add(LineComponent.builder()
                .left("Shards:")
                .right(String.valueOf(shardCount))
                .rightColor(shardCount > 0 ? SHARD_DROP_COLOR : DEFAULT_TEXT_COLOR)
                .build());

        // 4. Calculate and Format Time
        Duration elapsed = Duration.between(plugin.getStartTime(), Instant.now());
        long s = elapsed.getSeconds();
        String formattedTime = String.format("%02d:%02d:%02d", s / 3600, (s % 3600) / 60, s % 60);

        panelComponent.getChildren().add(LineComponent.builder()
                .left("Time:")
                .right(formattedTime)
                .build());

        return super.render(graphics);
    }
}

package com.vyrewatchhelper;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("vyrewatchhelper")
public interface VyrewatchHelperconfig extends Config
{
	@ConfigItem(
			keyName = "lowPrayerAlert",
			name = "Low Prayer Alert",
			description = "Notify when prayer drops below a threshold",
			position = 1
	)
	default boolean lowPrayerAlert() { return true; }

	@ConfigItem(
			keyName = "prayerThreshold",
			name = "Prayer Threshold",
			description = "The prayer level to trigger the alert",
			position = 2
	)
	default int prayerThreshold() { return 10; }

	@ConfigItem(
			keyName = "bloodShardAlert",
			name = "Blood Shard Notification",
			description = "Send a desktop notification when a Blood Shard drops",
			position = 3
	)
	default boolean bloodShardAlert() { return true; }
}

package com.vyrewatchhelper;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class VyrewatchPluginTest
{
    public static void main(String[] args) throws Exception
    {
        // This tells the test client to force-load your custom plugin on startup
        ExternalPluginManager.loadBuiltin(VyrewatchHelperPlugin.class);
        RuneLite.main(args);
    }
}
